bad_example:
for _, v := range items {
    go func() { process(v) }()
}

good_example:
for _, v := range items {
    v := v
    go func() { process(v) }()
}

bad_example:
func hacer() error {
    var err *MiError = nil
    if huboProblema {
        err = &MiError{}
    }
    return err // si huboProblema es false, esto NO es == nil para el caller
}

good_example:
func hacer() error {
    if huboProblema {
        return &MiError{}
    }
    return nil // nil literal, sin tipo dinamico adjunto
}

bad_example:
for k, v := range configMap {
    fmt.Println(k, v) // orden distinto en cada corrida
}

good_example:
keys := make([]string, 0, len(configMap))
for k := range configMap {
    keys = append(keys, k)
}
sort.Strings(keys)
for _, k := range keys {
    fmt.Println(k, configMap[k]) // orden estable y reproducible
}

bad_example:
func procesarTodos(rutas []string) error {
    for _, ruta := range rutas {
        f, err := os.Open(ruta)
        if err != nil { return err }
        defer f.Close() // se acumulan TODOS hasta que procesarTodos retorna
        procesar(f)
    }
    return nil
}

good_example:
func procesarUno(ruta string) error {
    f, err := os.Open(ruta)
    if err != nil { return err }
    defer f.Close() // se ejecuta al terminar ESTA llamada
    return procesar(f)
}

func procesarTodos(rutas []string) error {
    for _, ruta := range rutas {
        if err := procesarUno(ruta); err != nil { return err }
    }
    return nil
}

