original := []int{1, 2, 3, 4, 5}
sub := original[1:3] // [2,3], cap compartida con original
sub = append(sub, 99) // puede sobreescribir original[3] silenciosamente

if err != nil {
    return fmt.Errorf("guardando usuario: %v", err) // errors.Is(err, sql.ErrNoRows) ya no funciona arriba
}

good_example:
if err != nil {
    return fmt.Errorf("guardando usuario: %w", err) // preserva la cadena para errors.Is/errors.As
}

bad_example:
func trabajar(ch chan int) {
    resultado := calcular()
    ch <- resultado // si nadie mas recibe (ej. el caller ya retorno por timeout), esta goroutine queda bloqueada para siempre
}

good_example:
func trabajar(ctx context.Context, ch chan int) {
    resultado := calcular()
    select {
    case ch <- resultado:
    case <-ctx.Done():
        return // no se bloquea para siempre si el contexto se cancelo
    }
}
